!function(){const e=document.getElementById("fraction"),t=document.querySelectorAll(".swiper-slide").length;e.innerHTML=`01 <span>/ 0${t}</span>`;const n=()=>{setTimeout((()=>{const e=document.querySelector(".swiper-slide-active img");if(e){const t=e.src;document.querySelector("#main-Highlights").style.backgroundImage=`url('${t}')`}}),50)};var o=new Swiper(".swiper-Highlights",{effect:"fade",pagination:{el:".swiper-pagination-Highlights",type:"progressbar"},navigation:{nextEl:".swiper-button-next-Highlights",prevEl:".swiper-button-prev-Highlights"},on:{init:()=>{n()},slideChange:()=>{e.innerHTML=`0${o.realIndex+1} <span>/ 0${t}</span>`,n()}}});const s=document.getElementById("burgerButton"),l=document.getElementById("fixedMenu");s.addEventListener("click",(()=>{l.classList.add("open"),document.body.classList.add("no-scroll")})),l.querySelector("#closeMenu").addEventListener("click",(()=>{l.classList.remove("open"),document.body.classList.remove("no-scroll")}));const c=document.querySelectorAll(".modal"),i=document.querySelector("#modal"),d=document.querySelectorAll(".closeModal");c.forEach((e=>{e.addEventListener("click",(e=>{e.preventDefault(),i.classList.add("active"),document.body.classList.add("no-scroll")}))})),d.forEach((e=>{e.addEventListener("click",(e=>{e.preventDefault(),i.classList.remove("active"),document.body.classList.remove("no-scroll")}))})),document.addEventListener("DOMContentLoaded",(function(){var e=document.getElementById("mainNavigation");window.addEventListener("scroll",(function(){window.scrollY>200?e.classList.add("scrolled"):e.classList.remove("scrolled")}))}))}();